begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008001','calendar-admin@test.local'),('00000000-0000-4000-8000-000000008002','calendar-parent@test.local'),('00000000-0000-4000-8000-000000008003','calendar-other@test.local');
insert into public.operations_members(user_id,role,expires_at) values('00000000-0000-4000-8000-000000008001','content',now()+interval '1 day');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000008001','Calendar family','00000000-0000-4000-8000-000000008002');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008002');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008001','10000000-0000-4000-8000-000000008001','Child',2);
create function pg_temp.ch() returns uuid language sql as $$select '20000000-0000-4000-8000-000000008001'::uuid$$;
create function pg_temp.place() returns uuid language sql as $$select 'ec000000-0000-4000-8000-000000008001'::uuid$$;
create function pg_temp.cal() returns uuid language sql as $$select 'ca000000-0000-4000-8000-000000008001'::uuid$$;
create function pg_temp.year() returns int language sql as $$select extract(year from current_date)::int-1$$;
create function pg_temp.value() returns jsonb language sql as $$select jsonb_build_object('title','Verified school calendar','source_url','https://school.example/calendar','verified_on',current_date,'starts_on',make_date(pg_temp.year(),9,1),'ends_on',make_date(pg_temp.year()+1,6,30),'terms',jsonb_build_array(jsonb_build_object('title','Term 1','starts_on',make_date(pg_temp.year(),9,1),'ends_on',make_date(pg_temp.year()+1,1,20)),jsonb_build_object('title','Term 2','starts_on',make_date(pg_temp.year()+1,2,1),'ends_on',make_date(pg_temp.year()+1,6,30))))$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008001","role":"authenticated","gina":{"role":"parent"}}',true);
select lives_ok($$select public.admin_save_education_place(gen_random_uuid(),pg_temp.place(),0,jsonb_build_object('kind','school','parent_id','ec000000-0000-4000-8000-000000000001','name','Özel Okul','active',true))$$,'content operator adds canonical school');
select lives_ok($$select public.admin_save_education_calendar('70000000-0000-4000-8000-000000008001',pg_temp.cal(),0,pg_temp.place(),'primary',pg_temp.year(),pg_temp.value(),false)$$,'draft saved');
select lives_ok($$select public.admin_save_education_calendar('70000000-0000-4000-8000-000000008001',pg_temp.cal(),0,pg_temp.place(),'primary',pg_temp.year(),pg_temp.value(),false)$$,'same request safely replayed');
select is(public.admin_education_calendars()->'calendars'->0->'published','null'::jsonb,'draft does not become live');
select throws_ok($$select public.admin_save_education_calendar(gen_random_uuid(),pg_temp.cal(),0,pg_temp.place(),'primary',pg_temp.year(),pg_temp.value(),false)$$,'P0001','calendar_changed','stale draft rejected');
select throws_ok($$select public.admin_save_education_calendar(gen_random_uuid(),pg_temp.cal(),1,pg_temp.place(),'primary',pg_temp.year(),pg_temp.value()||'{"title":"Changed at publish"}',true)$$,'P0001','calendar_save_first','cannot publish unsaved changes');
select lives_ok($$select public.admin_save_education_calendar(gen_random_uuid(),pg_temp.cal(),1,pg_temp.place(),'primary',pg_temp.year(),pg_temp.value(),true)$$,'separate explicit publication');
select lives_ok($$select public.admin_save_education_calendar(gen_random_uuid(),pg_temp.cal(),2,pg_temp.place(),'primary',pg_temp.year(),pg_temp.value()||'{"title":"Draft only"}',false)$$,'live calendar can have unpublished draft');
select is(public.admin_education_calendars()->'calendars'->0->'published'->>'title','Verified school calendar','draft does not overwrite published source');
select throws_ok($$select public.admin_save_education_place(gen_random_uuid(),pg_temp.place(),1,jsonb_build_object('kind','school','parent_id','ec000000-0000-4000-8000-000000000001','name','Özel Okul','active',false))$$,'P0001','calendar_place_in_use','published scope cannot be hidden');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008002","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000008001"}}',true);
select is(public.preview_education_calendar(pg_temp.ch(),pg_temp.place(),'primary',pg_temp.year(),'initial',make_date(pg_temp.year(),9,1))->'calendar'->>'id',pg_temp.cal()::text,'parent sees verified school scope');
select is(public.preview_education_calendar(pg_temp.ch(),pg_temp.place(),'primary',pg_temp.year(),'initial',make_date(pg_temp.year(),8,25))->>'warning','outside_year','early private school date warns');
select is(public.preview_education_calendar(pg_temp.ch(),pg_temp.place(),'primary',pg_temp.year(),'new_year',make_date(pg_temp.year(),10,1))->>'warning','outside_transition','midyear promotion warns');
select throws_ok($$select public.admin_education_calendars()$$,'42501','forbidden','parent cannot see admin report queue');
select throws_ok($$select public.change_child_education_with_calendar(gen_random_uuid(),pg_temp.ch(),0,'initial',pg_temp.year(),2,'Özel Okul',make_date(pg_temp.year(),8,25),0,true,pg_temp.place(),'primary',pg_temp.cal(),2,null,null)$$,'P0001','calendar_reason_required','out of calendar requires a reason on server');
select throws_ok($$select public.change_child_education_with_calendar(gen_random_uuid(),pg_temp.ch(),0,'initial',pg_temp.year(),2,'Özel Okul',make_date(pg_temp.year(),8,25),0,true,pg_temp.place(),'primary',pg_temp.cal(),1,'school_calendar','School starts early')$$,'P0001','calendar_changed','stale published revision rejected');
select throws_ok($$select public.change_child_education_with_calendar(gen_random_uuid(),pg_temp.ch(),0,'initial',pg_temp.year(),2,'Özel Okul',make_date(pg_temp.year(),8,25),0,true,pg_temp.place(),'high',null,null,'calendar_missing',null)$$,'P0001','calendar_grade_mismatch','wrong stage cannot select irrelevant calendar');
select lives_ok($$select public.change_child_education_with_calendar('70000000-0000-4000-8000-000000008002',pg_temp.ch(),0,'initial',pg_temp.year(),2,'Özel Okul',make_date(pg_temp.year(),8,25),0,true,pg_temp.place(),'primary',pg_temp.cal(),2,'school_calendar','School confirms early start on its calendar')$$,'parent override preserves autonomy');
select lives_ok($$select public.change_child_education_with_calendar('70000000-0000-4000-8000-000000008002',pg_temp.ch(),0,'initial',pg_temp.year(),2,'Özel Okul',make_date(pg_temp.year(),8,25),0,true,pg_temp.place(),'primary',pg_temp.cal(),2,'school_calendar','School confirms early start on its calendar')$$,'retry does not duplicate period or report');
select is(public.get_child_education(pg_temp.ch())->>'revision','1','single education transition');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),1,'correct',pg_temp.year(),3,'Özel Okul',make_date(pg_temp.year(),8,25),0,true)$$,'P0001','calendar_review_required','legacy client cannot bypass calendar review');
select ok(not has_function_privilege('authenticated','gina.change_child_education(uuid,uuid,int,text,int,int,text,date,int,boolean)','execute'),'private unchecked transition is inaccessible');
select ok(not has_table_privilege('authenticated','gina.education_calendar_reports','SELECT'),'reports cannot be directly read');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008001","role":"authenticated","gina":{"role":"parent"}}',true);
select is(public.admin_education_calendars()->>'open_reports','1','exactly one school report queued');
select ok(not (public.admin_education_calendars()->'reports'->0 ? 'child_id'),'queue hides child identifiers');
select is(public.admin_education_calendars()->'calendars'->0->'published'->>'starts_on',make_date(pg_temp.year(),9,1)::text,'parent report did not mutate shared calendar');
select lives_ok(format('select public.admin_review_education_report(gen_random_uuid(),%L,1,%L,%L)',public.admin_education_calendars()->'reports'->0->>'id','verified','Confirmed with published school calendar https://school.example/calendar'),'operator records verification separately');
select is(public.admin_education_calendars()->>'open_reports','0','resolved report leaves queue');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008003","role":"authenticated","gina":{"role":"parent"}}',true);
select throws_ok($$select public.preview_education_calendar(pg_temp.ch(),pg_temp.place(),'primary',pg_temp.year(),'initial',current_date)$$,'42501','education_forbidden','other account cannot query child context');
reset role;
insert into gina.education_calendars(place_id,stage,academic_year,draft,published,published_revision) values('ec000000-0000-4000-8000-000000000001','primary',pg_temp.year(),pg_temp.value(),pg_temp.value()||'{"title":"Country primary"}',1),('ec000000-0000-4000-8000-000000000001','middle',pg_temp.year(),pg_temp.value(),pg_temp.value()||'{"title":"Country middle"}',1),('ec000000-0000-4000-8000-000000000001','university',pg_temp.year(),pg_temp.value(),pg_temp.value()||'{"title":"University calendar"}',1);
select is(gina.education_calendar_match(pg_temp.place(),'primary',pg_temp.year())->'value'->>'title','Verified school calendar','school publication takes precedence over country');
select is(gina.education_calendar_match(pg_temp.place(),'middle',pg_temp.year())->'value'->>'title','Country middle','fallback applies only to the matching stage and year');
select is(gina.education_calendar_match(pg_temp.place(),'university',pg_temp.year())->'value'->>'title','University calendar','university calendar is a separate stage');
select is(gina.education_calendar_match(pg_temp.place(),'primary',pg_temp.year()+2),null::jsonb,'never reuse an old calendar for a new year');
select is(gina.education_calendar_warning(gina.education_calendar_match(pg_temp.place(),'primary',pg_temp.year()),'transfer',make_date(pg_temp.year()+1,1,25)),'outside_term','recess date warns without silently changing calendar');
update public.operations_members set revoked_at=now() where user_id='00000000-0000-4000-8000-000000008001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008001","role":"authenticated","gina":{"role":"parent"}}',true);
select throws_ok($$select public.admin_education_calendars()$$,'42501','forbidden','revoked content operator loses access immediately');
select * from finish();rollback;
